update public.sea_raster
   set cells = set_bit(set_bit(set_bit(set_bit(set_bit(set_bit(cells, 396086, 1), 594844, 1), 597724, 1), 1067886, 1), 1070766, 1), 1119780, 1)
 where id = 1;
