-- ── 1b. THE ZONE OF AN OPENED CELL ──────────────────────────────────────────────────────────────
-- public.sea_zone_cells (0215) is the sea raster answered as zones, "every water cell gets a zone". A cell a
-- channel opens after 0215 is named in public.sea_cells and had no zone: 0440's six cells (the Corfu channels,
-- the Wielingen, the Tsugaru strait) answer none, and Messina's roadstead now lies in such a cell (a harbour
-- with no sea of its own). Every carved cell of every channel that is water with no zone takes the zone the
-- box rule gives its sea at its centre (0215's own rule, asked cell by cell).
do $$
declare
  c     record;
  v_sea int;
  v_ord int;
  v_n   int := 0;
begin
  for c in select distinct (k.v)::int / 1440 as r, (k.v)::int % 1440 as col
             from voyage.channels ch cross join lateral jsonb_array_elements_text(ch.carved_cells) k(v) order by 1, 2 loop
    select get_byte(s.seas, c.col) into v_sea from public.sea_cells s where s.row_idx = c.r;
    continue when v_sea is null or v_sea = 0;
    continue when (select get_byte(z.zones, c.col) from public.sea_zone_cells z where z.row_idx = c.r) <> 0;
    select z.ord into v_ord
      from public.sea_zone_boxes b join public.seas s on s.id = b.sea_id join public.sea_zones z on z.code = b.zone_code
     where s.raster_ordinal = v_sea
       and (b.lat_min is null or 90 - (c.r + 0.5) * 0.25 >= b.lat_min) and (b.lat_max is null or 90 - (c.r + 0.5) * 0.25 < b.lat_max)
       and (b.lon_min is null or (c.col + 0.5) * 0.25 - 180 >= b.lon_min) and (b.lon_max is null or (c.col + 0.5) * 0.25 - 180 < b.lon_max)
     order by b.ord limit 1;
    if v_ord is null then
      raise exception '0446 self-assert FAIL: the carved cell (row %, col %) of sea % is in no zone box', c.r, c.col, v_sea;
    end if;
    update public.sea_zone_cells z set zones = set_byte(z.zones, c.col, v_ord) where z.row_idx = c.r;
    v_n := v_n + 1;
  end loop;
  raise notice '0446: % carved cell(s) that were water with no zone now answer one', v_n;
  if exists (select 1 from voyage.channels ch cross join lateral jsonb_array_elements_text(ch.carved_cells) k(v)
              join public.sea_cells s on s.row_idx = (k.v)::int / 1440 join public.sea_zone_cells z on z.row_idx = s.row_idx
             where (get_byte(s.seas, (k.v)::int % 1440) <> 0) <> (get_byte(z.zones, (k.v)::int % 1440) <> 0)) then
    raise exception '0446 self-assert FAIL: a carved cell is water with no zone, or land with one';
  end if;
end
$$;

-- ── 2. THE ROADSTEADS ────────────────────────────────────────────────────────────────────────────
-- (no roadstead on drawn land or in a pocket: voyage.drawn_roadsteads is not touched)
-- The roadstead each harbour is reached from: what voyage.water_roadstead now answers for its quay.
update public.sea_reaches sr
   set roadstead_lat = w.lat, roadstead_lon = w.lon, snap_nm = w.nm
  from public.ports p
 cross join lateral voyage.water_roadstead(p.lat, p.lon) w
 where p.id = sr.port_id and p.code in ('MES');

