create function pg_temp.rev_0446(p jsonb) returns jsonb language sql immutable as $r$
  select jsonb_agg(t.x order by t.i desc) from jsonb_array_elements(p) with ordinality t(x, i)
$r$;

create function pg_temp.nm_0446(p jsonb) returns numeric language sql stable as $n$
  select sum((x ->> 'nm')::numeric) from jsonb_array_elements(voyage.segments_from_course(p)) x
$n$;

-- The named pairs of harbours, one on each side of a strait: the course the course author plots between
-- their roadsteads (through the strait), the straight line between them, and how far over it the course may be.
create function pg_temp.pass_0446() returns table (strait text, a text, b text, course jsonb, within numeric) language sql immutable as $p$
  select v.strait, v.a, v.b, v.course::jsonb, v.within from (values
    ('messina', 'MES', 'ZAK', '[[38.185, 15.592], [37.9625, 15.6375], [37.9125, 15.7875], [37.9375, 20.7375], [37.887, 20.788]]', 1.2::numeric),
    ('messina', 'NAP', 'ZAK', '[[40.625, 14.125], [38.2625, 15.6375], [37.9875, 15.6125], [37.9125, 15.7875], [37.9375, 20.7375], [37.887, 20.788]]', 1.3::numeric),
    ('great-belt', 'LUB', 'BER', '[[54.125, 11.125], [54.4375, 11.3125], [54.7875, 10.9875], [56.125, 10.875], [56.375, 11.125], [56.9092, 10.9915], [57.5125, 10.7375], [57.875, 10.375], [57.875, 6.875], [58.2541, 5.9271], [58.5125, 5.4875], [59.125, 5.125], [60.375, 4.875]]', 1.3::numeric),
    ('bangka', 'BNT', 'LGA', '[[-5.875, 106.125], [-3.1792, 106.3701], [-2.9875, 106.2375], [-2.7875, 105.9375], [-2.4875, 105.7375], [-2.3875, 105.6125], [-2.0625, 105.1125], [-0.262, 104.663]]', 1.15::numeric),
    ('surabaya', 'JAK', 'SUR', '[[-5.875, 106.875], [-6.4125, 111.0375], [-6.6018, 112.2047], [-6.7625, 112.5125], [-6.9125, 112.6125], [-7.1875, 112.7375], [-7.212, 112.863]]', 1.1::numeric)
  ) as v(strait, a, b, course, within)
$p$;

-- THE ONE STEP (0440's, unchanged): every row that holds a replaced course takes the new one; a cargo circuit's and a
-- navy patrol's frozen pieces (0309, 0331) of a replaced lane or coast course are re-cut, either way round.
create function pg_temp.clear_0446() returns jsonb language plpgsql as $c$
declare
  v_lanes int;
  v_stops int;
  v_coast int;
  v_legs  int := 0;
  v_patrol int := 0;
  v_memo  int;
  v_keep  jsonb;
  l       record;
  v_in    jsonb;
  v_out   jsonb;
  v_n     int;
  v_i     int;
  v_hit   record;
  v_moved boolean;
begin
  create temp table recut_0446 on commit drop as
  select distinct on (x.old) ((x.old -> 0 -> 'a')::text || (x.old -> 0 -> 'b')::text) as head, x.old, x.new, jsonb_array_length(x.old) as n
    from (select voyage.segments_from_course(q.c) as old, voyage.segments_from_course(q.n) as new
            from (select c.course as c, f.course as n
                    from (select course from public.npc_courses union select course from public.npc_coast_courses) c
                    join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5
                  union all
                  select pg_temp.rev_0446(c.course), pg_temp.rev_0446(f.course)
                    from (select course from public.npc_courses union select course from public.npc_coast_courses) c
                    join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5) q) x
   order by x.old;
  create index on recut_0446 (head);
  -- ONE PASS, LEFT TO RIGHT: at each piece of a leg, the LONGEST replaced lane whose pieces the leg holds there,
  -- piece for piece (by their ends), is swapped for its new pieces, and the walk goes on past it.
  for l in select 'cargo' as k, g.circuit_id as id, g.ord, g.segments as s from public.cargo_circuit_legs g
           union all
           select 'patrol', n.station_id, n.ord, n.segments from public.navy_patrol_legs n loop
    v_in := l.s;
    v_n := jsonb_array_length(v_in);
    v_out := '[]'::jsonb;
    v_i := 0;
    v_moved := false;
    while v_i < v_n loop
      select r.new, r.n into v_hit
        from recut_0446 r
       where r.head = (v_in -> v_i -> 'a')::text || (v_in -> v_i -> 'b')::text
         and r.n <= v_n - v_i
         and not exists (select 1 from generate_series(0, r.n - 1) k
                          where (r.old -> k -> 'a') is distinct from (v_in -> (v_i + k) -> 'a')
                             or (r.old -> k -> 'b') is distinct from (v_in -> (v_i + k) -> 'b'))
       order by r.n desc
       limit 1;
      if found then
        v_out := v_out || v_hit.new;
        v_i := v_i + v_hit.n;
        v_moved := true;
      else
        v_out := v_out || jsonb_build_array(v_in -> v_i);
        v_i := v_i + 1;
      end if;
    end loop;
    if v_moved and v_out is distinct from v_in then
      if l.k = 'cargo' then
        update public.cargo_circuit_legs g
           set segments = v_out, nm = (select sum((x ->> 'nm')::numeric) from jsonb_array_elements(v_out) x)
         where g.circuit_id = l.id and g.ord = l.ord;
        v_legs := v_legs + 1;
      else
        update public.navy_patrol_legs n
           set segments = v_out, nm = (select sum((x ->> 'nm')::numeric) from jsonb_array_elements(v_out) x)
         where n.station_id = l.id and n.ord = l.ord;
        v_patrol := v_patrol + 1;
      end if;
    end if;
  end loop;
  drop table recut_0446;

  update public.npc_courses c set course = f.course, nm = pg_temp.nm_0446(f.course)
    from pg_temp.fix_0446() f where md5(c.course::text) = f.old_md5;
  get diagnostics v_lanes = row_count;

  update public.npc_coast_courses c set course = f.course, nm = pg_temp.nm_0446(f.course)
    from pg_temp.fix_0446() f where md5(c.course::text) = f.old_md5;
  get diagnostics v_coast = row_count;

  update public.standing_route_stops s set course = f.course, course_nm = pg_temp.nm_0446(f.course)
    from pg_temp.fix_0446() f where md5(s.course::text) = f.old_md5;
  get diagnostics v_stops = row_count;

  insert into public.npc_course_zones_memo (course_md5, zones)
  select distinct on (k.h) k.h, k.zones
    from (select md5(f.course::text) as h, public.course_zones(f.course) as zones from pg_temp.fix_0446() f
          union all
          select md5(pg_temp.rev_0446(f.course)::text), public.course_zones(f.course) from pg_temp.fix_0446() f) k
   order by k.h
  on conflict (course_md5) do nothing;
  get diagnostics v_memo = row_count;

  -- THE PAIR TABLE KEEPS STEP (0442): a re-sailed lane may cross a sea its pair's row does not hold, and a moved
  -- roadstead may lie in another sea than its own row names. PART B then re-ships the rows from a new build.
  v_keep := public.sea_leg_asks_keep();

  return jsonb_build_object('lanes', v_lanes, 'stops', v_stops, 'coast', v_coast, 'cargo_legs', v_legs, 'patrol_legs', v_patrol, 'memo', v_memo, 'pair_table', v_keep);
end
$c$;

-- ── 4. SELF-ASSERT, on properties, with a probe that is rolled back ─────────────────────────────
do $$
declare
  v_join  numeric := public.wc_num('course_join_nm');
  v_bad   text;
  v_old   jsonb;
  v_new   jsonb;
  v_old2  jsonb;
  v_new2  jsonb;
  v_nat   uuid;
  v_circ  bigint;
  v_station bigint;
  v_port  uuid;
  v_got   jsonb;
  v_want  jsonb;
  v_res   jsonb;
begin
  -- (a) THE RASTER: every charted cell is water, and each charted channel lists exactly its cells.
  select string_agg(c.k::text, ' ') into v_bad
    from (values (198043), (297422), (298862), (533943), (535383), (559890)) c(k), public.sea_raster r
   where r.id = 1 and get_bit(r.cells, c.k * r.bits_per_cell) <> 1;
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: charted cell(s) not water: %', v_bad;
  end if;
  if (select count(*) from voyage.channels c where c.id in ('messina', 'great-belt', 'bangka', 'surabaya') and jsonb_array_length(c.carved_cells) = c.opens_land) <> 4 then
    raise exception '0446 self-assert FAIL: a charted channel is missing from voyage.channels';
  end if;

  -- (b) THE CONTROLS, AFTER: each strait's own line, every sample read (no approach), is water.
  if voyage.path_refusal('[[38.4,15.48],[38.32,15.62],[38.29,15.67],[38.272,15.695],[38.257,15.66],[38.245,15.62],[38.23,15.6],[38.2,15.595],[38.175,15.59],[38.15,15.585],[38.1,15.57],[38.05,15.56],[38.01,15.56],[37.97,15.57]]'::jsonb, 38.4, 15.48, 37.97, 15.57, 0, 0, 0) is not null then
    raise exception '0446 self-assert FAIL: messina is still refused down its own line: %', voyage.path_refusal('[[38.4,15.48],[38.32,15.62],[38.29,15.67],[38.272,15.695],[38.257,15.66],[38.245,15.62],[38.23,15.6],[38.2,15.595],[38.175,15.59],[38.15,15.585],[38.1,15.57],[38.05,15.56],[38.01,15.56],[37.97,15.57]]'::jsonb, 38.4, 15.48, 37.97, 15.57, 0, 0, 0);
  end if;
  if voyage.path_refusal('[[55.47,10.88],[55.56,10.85],[55.66,10.83],[55.74,10.82],[55.8,10.8]]'::jsonb, 55.47, 10.88, 55.8, 10.8, 0, 0, 0) is not null then
    raise exception '0446 self-assert FAIL: great-belt is still refused down its own line: %', voyage.path_refusal('[[55.47,10.88],[55.56,10.85],[55.66,10.83],[55.74,10.82],[55.8,10.8]]'::jsonb, 55.47, 10.88, 55.8, 10.8, 0, 0, 0);
  end if;
  if voyage.path_refusal('[[-2.4,105.76],[-2.55,105.76],[-2.7,105.83],[-2.85,105.86],[-2.92,105.95],[-2.97,106.1]]'::jsonb, -2.4, 105.76, -2.97, 106.1, 0, 0, 0) is not null then
    raise exception '0446 self-assert FAIL: bangka is still refused down its own line: %', voyage.path_refusal('[[-2.4,105.76],[-2.55,105.76],[-2.7,105.83],[-2.85,105.86],[-2.92,105.95],[-2.97,106.1]]'::jsonb, -2.4, 105.76, -2.97, 106.1, 0, 0, 0);
  end if;
  if voyage.path_refusal('[[-6.95,112.7],[-7,112.7],[-7.03,112.67],[-7.045,112.68],[-7.056,112.675],[-7.07,112.66],[-7.11,112.67],[-7.135,112.68],[-7.155,112.7],[-7.18,112.715],[-7.195,112.76],[-7.195,112.8]]'::jsonb, -6.95, 112.7, -7.195, 112.8, 0, 0, 0) is not null then
    raise exception '0446 self-assert FAIL: surabaya is still refused down its own line: %', voyage.path_refusal('[[-6.95,112.7],[-7,112.7],[-7.03,112.67],[-7.045,112.68],[-7.056,112.675],[-7.07,112.66],[-7.11,112.67],[-7.135,112.68],[-7.155,112.7],[-7.18,112.715],[-7.195,112.76],[-7.195,112.8]]'::jsonb, -6.95, 112.7, -7.195, 112.8, 0, 0, 0);
  end if;

  -- (c) THE ROADSTEADS: every changed harbour is reached from the point this file measured, by the rule and by
  --     the table; the helper line is the distance (gc(quay, roads) = snap_nm); and the point is raster water (0441).
  select string_agg(v.code, ' ') into v_bad
    from (values
      ('MES', 38.185::numeric, 15.592::numeric)
         ) v(code, lat, lon)
    join public.ports p on p.code = v.code
    join public.sea_reaches sr on sr.port_id = p.id
   cross join lateral voyage.water_roadstead(p.lat, p.lon) w
   cross join public.sea_raster r
   where r.id = 1
     and (w.lat <> v.lat or w.lon <> v.lon or sr.roadstead_lat <> v.lat or sr.roadstead_lon <> v.lon
      or abs(sr.snap_nm - voyage.gc_distance_nm(p.lat::float8, p.lon::float8, v.lat::float8, v.lon::float8)::numeric) > 0.001
      or get_bit(r.cells, (floor((90 - v.lat) / r.cell_deg)::int * r.cols + floor((v.lon + 180) / r.cell_deg)::int) * r.bits_per_cell) <> 1);
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: these roadsteads are not what this file measured, or are not raster water: %', v_bad;
  end if;

  -- (c2) EVERY HARBOUR HAS A SEA OF ITS OWN: its roadstead answers a zone (Messina's lies in an opened cell).
  select string_agg(p.code, ' ') into v_bad from public.ports p where p.kind = 'HARBOUR' and public.harbour_zone(p.id) is null;
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: these harbours'' roadsteads answer no sea: %', v_bad;
  end if;

  -- (d) THE SERVER'S LAW: every new course is raster water as cmd.do_sail judges a roads-to-roads course.
  select string_agg(f.old_md5 || ': ' || r.ref, '; ') into v_bad
    from pg_temp.fix_0446() f
   cross join lateral (select voyage.path_refusal(f.course,
                                (f.course -> 0 ->> 0)::numeric, (f.course -> 0 ->> 1)::numeric,
                                (f.course -> -1 ->> 0)::numeric, (f.course -> -1 ->> 1)::numeric, v_join, 25, 25) as ref) r
   where r.ref is not null;
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: a re-sailed course is refused by voyage.path_refusal: %', left(v_bad, 2000);
  end if;

  -- (e) THE STRAITS ARE PASSABLE: between the named harbours on each side, the plotted course begins and ends at
  --     their roadsteads, is accepted by the server's law with every sample read, and is no longer than the
  --     stated multiple of the straight line between them. (Messina to Zakynthos: 291 nm before 0440, 630 after.)
  select string_agg(q.a || '-' || q.b || ' (' || q.strait || ')', ' ') into v_bad
    from pg_temp.pass_0446() q
    join public.ports pa on pa.code = q.a join public.sea_reaches ra on ra.port_id = pa.id
    join public.ports pb on pb.code = q.b join public.sea_reaches rb on rb.port_id = pb.id
   where (q.course -> 0 ->> 0)::numeric <> ra.roadstead_lat or (q.course -> 0 ->> 1)::numeric <> ra.roadstead_lon
      or (q.course -> -1 ->> 0)::numeric <> rb.roadstead_lat or (q.course -> -1 ->> 1)::numeric <> rb.roadstead_lon
      or voyage.path_refusal(q.course, ra.roadstead_lat, ra.roadstead_lon, rb.roadstead_lat, rb.roadstead_lon, 0, 0, 0) is not null
      or pg_temp.nm_0446(q.course) > q.within * voyage.gc_distance_nm(ra.roadstead_lat::float8, ra.roadstead_lon::float8, rb.roadstead_lat::float8, rb.roadstead_lon::float8)::numeric;
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: these straits are not passable between their named harbours: %', v_bad;
  end if;

  -- (f) THE PROBE, rolled back whole.
  begin
    -- THROUGH THE STRAIT, NOT ROUND IT: with a strait's cells closed again, the course between its named harbours
    -- is refused. So the short course is the strait's, and a change that closes the cells is seen by this law.
    update public.sea_raster set cells = set_bit(set_bit(cells, 594844, 0), 597724, 0) where id = 1;
    select string_agg(q.a || '-' || q.b, ' ') into v_bad from pg_temp.pass_0446() q
     where q.strait = 'messina'
       and voyage.path_refusal(q.course, (q.course -> 0 ->> 0)::numeric, (q.course -> 0 ->> 1)::numeric,
                               (q.course -> -1 ->> 0)::numeric, (q.course -> -1 ->> 1)::numeric, 0, 0, 0) is null;
    if v_bad is not null then
      raise exception '0446 self-assert FAIL: with messina closed again these courses are still accepted, so they do not run through it: %', v_bad;
    end if;
    update public.sea_raster set cells = set_bit(set_bit(cells, 594844, 1), 597724, 1) where id = 1;
    update public.sea_raster set cells = set_bit(cells, 396086, 0) where id = 1;
    select string_agg(q.a || '-' || q.b, ' ') into v_bad from pg_temp.pass_0446() q
     where q.strait = 'great-belt'
       and voyage.path_refusal(q.course, (q.course -> 0 ->> 0)::numeric, (q.course -> 0 ->> 1)::numeric,
                               (q.course -> -1 ->> 0)::numeric, (q.course -> -1 ->> 1)::numeric, 0, 0, 0) is null;
    if v_bad is not null then
      raise exception '0446 self-assert FAIL: with great-belt closed again these courses are still accepted, so they do not run through it: %', v_bad;
    end if;
    update public.sea_raster set cells = set_bit(cells, 396086, 1) where id = 1;
    update public.sea_raster set cells = set_bit(set_bit(cells, 1067886, 0), 1070766, 0) where id = 1;
    select string_agg(q.a || '-' || q.b, ' ') into v_bad from pg_temp.pass_0446() q
     where q.strait = 'bangka'
       and voyage.path_refusal(q.course, (q.course -> 0 ->> 0)::numeric, (q.course -> 0 ->> 1)::numeric,
                               (q.course -> -1 ->> 0)::numeric, (q.course -> -1 ->> 1)::numeric, 0, 0, 0) is null;
    if v_bad is not null then
      raise exception '0446 self-assert FAIL: with bangka closed again these courses are still accepted, so they do not run through it: %', v_bad;
    end if;
    update public.sea_raster set cells = set_bit(set_bit(cells, 1067886, 1), 1070766, 1) where id = 1;
    update public.sea_raster set cells = set_bit(cells, 1119780, 0) where id = 1;
    select string_agg(q.a || '-' || q.b, ' ') into v_bad from pg_temp.pass_0446() q
     where q.strait = 'surabaya'
       and voyage.path_refusal(q.course, (q.course -> 0 ->> 0)::numeric, (q.course -> 0 ->> 1)::numeric,
                               (q.course -> -1 ->> 0)::numeric, (q.course -> -1 ->> 1)::numeric, 0, 0, 0) is null;
    if v_bad is not null then
      raise exception '0446 self-assert FAIL: with surabaya closed again these courses are still accepted, so they do not run through it: %', v_bad;
    end if;
    update public.sea_raster set cells = set_bit(cells, 1119780, 1) where id = 1;

    -- A cargo circuit of its own whose one leg is two replaced lanes, the second read backwards. After the step its
    -- leg must be exactly the two new lanes' pieces; the same for a navy station's patrol leg.
    select c.course, f.course into v_old, v_new
      from public.npc_courses c join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5 order by f.old_md5 limit 1;
    select c.course, f.course into v_old2, v_new2
      from public.npc_courses c join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5 order by f.old_md5 desc limit 1;
    if v_old is not null then
      v_nat := (select g.nation_id from public.great_powers g order by g.nation_id limit 1);
      v_port := (select p.id from public.ports p where p.kind = 'HARBOUR' order by p.code limit 1);
      insert into public.cargo_circuits (nation_id, start_port) values (v_nat, v_port) returning id into v_circ;
      insert into public.cargo_circuit_legs (circuit_id, ord, to_port, nm, segments)
      values (v_circ, 1, v_port, 1, voyage.segments_from_course(v_old) || voyage.segments_from_course(pg_temp.rev_0446(v_old2)));
      v_station := (select s.id from public.navy_stations s order by s.id limit 1);
      if v_station is not null then
        insert into public.navy_patrol_legs (station_id, ord, to_port, nm, segments)
        values (v_station, 9999, v_port, 1, voyage.segments_from_course(v_old) || voyage.segments_from_course(pg_temp.rev_0446(v_old2)));
      end if;
      v_res := pg_temp.clear_0446();
      v_got := (select g.segments from public.cargo_circuit_legs g where g.circuit_id = v_circ and g.ord = 1);
      v_want := voyage.segments_from_course(v_new) || voyage.segments_from_course(pg_temp.rev_0446(v_new2));
      if v_got is distinct from v_want then
        raise exception '0446 self-assert FAIL: the probe cargo leg was not re-cut to the new lanes (% pieces, % wanted)',
          jsonb_array_length(v_got), jsonb_array_length(v_want);
      end if;
      if v_station is not null and (select n.segments from public.navy_patrol_legs n where n.station_id = v_station and n.ord = 9999) is distinct from v_want then
        raise exception '0446 self-assert FAIL: the probe patrol leg was not re-cut to the new lanes';
      end if;
    end if;
    raise exception using errcode = 'ZY446', message = coalesce(v_res, '{}'::jsonb)::text;
  exception when sqlstate 'ZY446' then
    raise notice '0446 probe (rolled back): each strait closed again refuses its course; the cargo and patrol legs re-cut: %', sqlerrm;
  end;
end
$$;

-- ── 5. THE STEP, for real ────────────────────────────────────────────────────────────────────────
do $$
declare
  v_res jsonb := pg_temp.clear_0446();
  v_bad text;
begin
  -- Lanes and coast courses are written only by migrations, so no row of theirs may still hold a replaced
  -- course, and none may be one the server's law refuses. (Route stops are not asserted: a player may save one.)
  if exists (select 1 from public.npc_courses c join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5)
     or exists (select 1 from public.npc_coast_courses c join pg_temp.fix_0446() f on md5(c.course::text) = f.old_md5) then
    raise exception '0446 self-assert FAIL: a lane or a coast course still holds a replaced course';
  end if;
  select string_agg(a.code || '-' || b.code, ' ') into v_bad
    from public.npc_courses c join public.ports a on a.id = c.from_port join public.ports b on b.id = c.to_port
   where voyage.path_refusal(c.course, (c.course -> 0 ->> 0)::numeric, (c.course -> 0 ->> 1)::numeric,
                             (c.course -> -1 ->> 0)::numeric, (c.course -> -1 ->> 1)::numeric, public.wc_num('course_join_nm'), 25, 25) is not null;
  if v_bad is not null then
    raise exception '0446 self-assert FAIL: these lanes are refused by the server''s law: %', left(v_bad, 1000);
  end if;
  raise notice '0446 PART A self-assert ok: THE REAL STRAITS ARE OPEN. 6 charted cells open in 4 straits (each line refused before, water after; each closed again refuses its course); 1 roadstead(s) as voyage.water_roadstead answers; 5 named pairs pass their strait within their multiple of the straight line; 46 course(s) re-sailed, every one raster water by voyage.path_refusal; the probe legs re-cut and rolled back. Rewritten: %', v_res;
end
$$;

