     or md5((select string_agg(p.code || ':' || sr.roadstead_lat || ',' || sr.roadstead_lon, ' ' order by p.code collate "C")
               from public.ports p join public.sea_reaches sr on sr.port_id = p.id where p.kind = 'HARBOUR')) <> '6915023be481f0fbf6cb8406e1cd7204'
     or md5((select encode(r.cells, 'hex') from public.sea_raster r where r.id = 1)) <> '50ff382d96e58da517491c2127519759'
     or md5((select string_agg(encode(c.zones, 'hex'), '' order by c.row_idx) from public.sea_zone_cells c)) <> 'a3e720b33624491c1cdf14a3eacb5482' then
