          from seed_0446 s cross join lateral jsonb_array_elements(s.j -> 'legs') with ordinality r(leg, i)
         cross join lateral jsonb_array_elements_text(r.leg) with ordinality e(k, j)) lg
  join h_0446 hf on hf.i = lg.fi join h_0446 ht on ht.i = lg.ti join st_0446 st on st.k = lg.k;
alter table new_0446 add primary key (from_port, to_port);
analyze new_0446;

update public.sea_leg_asks s
   set zones = n.zones
  from new_0446 n
 where n.from_port = s.from_port and n.to_port = s.to_port and n.known and s.zones is distinct from n.zones;

