,"MUM":2507.9,"MUS":2239.3,"MWY":8951.6,"MYE":3747.2,"MZT":11203.2,"NAG":6447.1,"NAH":6101.2,"NAM":6661.2,"NAN":8268.5,"NAP":8527.5,"NAV":10930.9,"NEW":9226.5,"NIN":6132.6,"NUU":9321.8,"OLD":2447.3,"OPO":7688.7,"ORA":7795.9,"OSA":6725.4,"OUI":5046.2,"PAI":9226.3,"PAL":8446.2,"PAN":10074.3,"PAR":7316.3,"PAT":8873.6,"PLM":8011,"PLO":1377.7,"PLY":8316.8,"PON":7533.8,"POR":8728.4,"PRT":8916.7,"PTC":9074.9,"PTH":8419.2,"PTL":9155.7,"PTT":4522.1,"PUL":2897.2,"PUS":10473.3,"QUA":5720.6,"QUE":9439.7,"REA":10309.2,"REC":5734.8,"REY":9027.2,"RHO":9206.4,"RIG":9634.3,"RIO":5673.3,"ROT":8627.8,"RRF":2302.4,"SAF":7250.6,"SAI":6177,"SAK":6725.4,"SAL":7416.9,"SAN":8235.8,"SAO":4646.1,"SDG":11992,"SET":7530.4,"SFR":11662.4,"SGO":8368.6,"SGS":8250.2,"SHI":6582.8,"SKC":3462.8,"SLV":5744.9,"SNL":7535.7,"SNT":8350.6,"SOF":1026.8,"SOG":7545.5,"SOH":2459.1,"SOM":3835.2,"SOS":5804.5,"SOY":4211.5,"SPL":9043,"SRT":2564.4,"STA":9251.1,"STG":8596.6,"STJ":8640.7,"STO":9524.8,"SUA":2352.3,"SUE":3024.4,"SUR":4436.7,"SVQ":7575.5,"SYD":6465.2,"TAI":5666.6,"TAL":9712.5,"TAN":7524.1,"TDC":3910,"TEN":6860,"TER":5452.9,"THA":3738.4,"THE":9228.3,"TID":5490.2,"TOK":6947.8,"TON":6536.1,"TOR":8931.9,"TOU":8265.6,"TRA":9882.9,"TRI":9619.6,"TRO":9339.7,"TRP":8645.6,"TSU":6522.2,"TUN":8357,"TUR":9644.8,"ULS":6630,"VAL":7942.8,"VAR":10088.4,"VEN":9228.7,"VER":9902.5,"VIS":9441.3,"VLL":8554.4,"VLP":7553.6,"WIL":8246.7,"WLG":7167.8,"XIA":5680.5,"YEO":6492.9,"ZAK":8857.4}}$reach$::jsonb) e;
alter table reach_0446 add primary key (code);

do $r$
declare
  v_bad text;
  v_n   int;
begin
  if (select string_agg(sr.code, ' ' order by sr.code collate "C") from public.sea_reaches sr) is distinct from (select string_agg(r.code, ' ' order by r.code collate "C") from reach_0446 r) then
    raise exception '0446 refuses: the places of public.sea_reaches are not the ones the distances were measured for';
  end if;
  update public.sea_reaches sr set reaches = r.reaches from reach_0446 r where r.code = sr.code and sr.reaches is distinct from r.reaches;
  -- one answer both ways round, every place reaches every other, and no figure is shorter than the straight line between the two roadsteads
  select string_agg(a.code || '-' || b.code, ' '), count(*) into v_bad, v_n
    from public.sea_reaches a join public.sea_reaches b on b.code <> a.code
   where (a.reaches ->> b.code) is null or (a.reaches ->> b.code)::numeric <> (b.reaches ->> a.code)::numeric
      or (a.reaches ->> b.code)::numeric < voyage.gc_distance_nm(a.roadstead_lat::float8, a.roadstead_lon::float8, b.roadstead_lat::float8, b.roadstead_lon::float8) - 0.1;
  if v_n > 0 then
    raise exception '0446 self-assert FAIL: % pair(s) are not one distance both ways, or are shorter than the straight line: %', v_n, left(v_bad, 400);
  end if;
  -- THE PRICES: every market row's haul is the one derivation's answer again (0173, 0208, 0212's refill)
  update public.port_goods pg set haul_nm = h.haul_nm, haul = h.haul
    from world.haul_rows() h
   where h.port_id = pg.port_id and h.good_id = pg.good_id and (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul);
  get diagnostics v_n = row_count;
  if exists (select 1 from public.port_goods pg join world.haul_rows() h on h.port_id = pg.port_id and h.good_id = pg.good_id
              where (pg.haul_nm, pg.haul) is distinct from (h.haul_nm, h.haul)) then
    raise exception '0446 self-assert FAIL: a market row''s haul is not world.haul_rows()''s answer after the refill';
  end if;
  raise notice '0446: the quoted distances measured again; % market row(s) refilled from world.haul_rows()', v_n;
end
$r$;

-- ── 3. SELF-ASSERT, with a probe that is rolled back; then the step for real ──
do $m$
declare
  v_t0   timestamptz := clock_timestamp();
  v_h    int;
  v_res  jsonb;
  v_law  record;
  v_lane record;
  v_port uuid;
  v_zone text;
  v_other text;
  v_moved jsonb;
begin
  select count(*) into v_h from public.ports p where p.kind = 'HARBOUR';
  if (select count(*) from public.sea_leg_asks) <> v_h * v_h or (select count(*) from new_0446 n where n.known) <> v_h * v_h then
    raise exception '0446 self-assert FAIL: the pair table is not one row a pair of % harbours from the seed (% rows, % seed rows read)',
      v_h, (select count(*) from public.sea_leg_asks), (select count(*) from new_0446 n where n.known);
  end if;

  -- THE PROBE (rolled back): a row broken three ways is mended by the function, and nothing else moves.
  begin
    perform public.sea_leg_asks_keep();   -- the table in step first, so what the probe sees moved is the probe's
    select n.from_port, n.to_port, public.npc_course_zones(n.course) as zones into v_lane
      from public.npc_courses n where cardinality(public.npc_course_zones(n.course)) >= 2 order by n.from_port, n.to_port limit 1;
    select p.id, public.harbour_zone(p.id) into v_port, v_zone from public.ports p where p.kind = 'HARBOUR' order by p.code limit 1;
    select z.code into v_other from public.sea_zones z where z.code <> v_zone order by z.code limit 1;
    if v_lane.from_port is null or v_port is null or v_other is null then
      raise exception '0446 self-assert FAIL: the world holds no lane of two seas, no harbour or one sea only: the probe has nothing to break';
    end if;
    update public.sea_leg_asks s set zones = v_lane.zones[1:1], wave_min = 0, title_min = 0 where s.from_port = v_lane.from_port and s.to_port = v_lane.to_port;
    update public.sea_leg_asks s set zones = array[v_other] where s.from_port = v_port and s.to_port = v_port;
    select * into v_law from pg_temp.laws_0446();
    if v_law.own is null or v_law.lanes is null or v_law.asks < 1 then
      raise exception '0446 self-assert FAIL: the three laws do not see a row broken on purpose (own %, lanes %, asks %)', v_law.own, v_law.lanes, v_law.asks;
    end if;
    v_res := public.sea_leg_asks_keep();
    select * into v_law from pg_temp.laws_0446();
    if v_law.own is not null or v_law.lanes is not null or v_law.asks <> 0 or (v_res ->> 'own')::int <> 1 or (v_res ->> 'lanes')::int <> 1 or (v_res ->> 'asks')::int < 1
       or not (select s.zones @> v_lane.zones from public.sea_leg_asks s where s.from_port = v_lane.from_port and s.to_port = v_lane.to_port)
       or (select s.zones from public.sea_leg_asks s where s.from_port = v_port and s.to_port = v_port) is distinct from array[v_zone] then
      raise exception '0446 self-assert FAIL: the function did not mend the probe (%; own %, lanes %, asks %)', v_res, v_law.own, v_law.lanes, v_law.asks;
    end if;
    raise exception using errcode = 'ZX446', message = v_res::text;
  exception when sqlstate 'ZX446' then
    raise notice '0446 probe (rolled back): a lane row cut to one sea, a harbour''s own row given another sea: mended %', sqlerrm;
  end;

  -- THE STEP, for real
  v_res := public.sea_leg_asks_keep();
  select * into v_law from pg_temp.laws_0446();
  if v_law.own is not null or v_law.lanes is not null or v_law.asks <> 0 then
    raise exception '0446 self-assert FAIL: after the step, own rows off: %; lanes off their row: %; rows asking other than their seas: %', v_law.own, left(v_law.lanes, 600), v_law.asks;
  end if;
  -- Messina, by name: its own row is the sea its roadstead lies in (its roadstead moved into the strait)
  if not exists (select 1 from public.ports p join public.sea_leg_asks s on s.from_port = p.id and s.to_port = p.id
                   join pre_0446 o on o.from_port = p.id and o.to_port = p.id
                  where p.code = 'MES' and s.zones = array[public.harbour_zone(p.id)]) then
    raise exception '0446 self-assert FAIL: Messina''s own row is not its roadstead''s sea';
  end if;
  -- every row still holds every sea the seed gave it (the function only adds)
  if exists (select 1 from new_0446 n join public.sea_leg_asks s on s.from_port = n.from_port and s.to_port = n.to_port
              where n.known and n.from_port <> n.to_port and not s.zones @> n.zones) then
    raise exception '0446 self-assert FAIL: a row lost a sea of its plotted course';
  end if;
  select jsonb_build_object(
           'seas', count(*) filter (where s.zones <> o.zones),
           'asks', count(*) filter (where s.wave_min <> o.wave_min or s.title_min <> o.title_min),
           'more', count(*) filter (where s.wave_min > o.wave_min or s.title_min > o.title_min),
           'less', count(*) filter (where s.wave_min < o.wave_min or s.title_min < o.title_min)) into v_moved
    from public.sea_leg_asks s join pre_0446 o on o.from_port = s.from_port and o.to_port = s.to_port;

  comment on table public.sea_leg_asks is
    '0215, 0222, 0403, 0446: what a leg between two harbours asks. zones = the seas of the course the browser''s course author plots from the first '
    'roadstead to the second (scripts/build-sea-legs.mjs, data/sea-legs.json: the search, then the re-sailing off the coast mask), sampled by '
    'public.course_zones, with the seas of any course the world remembers on the pair (public.npc_courses); wave_min, title_min = the most those seas '
    'and the destination''s own sea ask. A harbour''s own row is its roadstead''s sea. Not hand-edited: a slice that moves a sea box, the raster, a '
    'roadstead or a harbour, or re-sails a remembered course, calls public.sea_leg_asks_keep() and re-runs the build. Read by public.sea_routes (Trade), '
    'voyage.reach_passage and public.sea_floor.';

  raise notice '0446 self-assert ok: THE PAIR TABLE KEEPS STEP WITH THE COURSES. % rows for % harbours from the plotted courses; the step: %; moved against the table as it was: %; own rows, lanes and asks all in step; Messina''s own row is its roadstead''s sea; the probe mended and rolled back. % ms',
    v_h * v_h, v_h, v_res, v_moved, round(extract(epoch from clock_timestamp() - v_t0) * 1000);
end
$m$;
